SET IDENTITY_INSERT [KPIs] ON;
INSERT INTO [KPIs] ([Id], [PeriodId], [KPIName], [Description], [PropertyId], [KPITypeId], [OKRId], [OKRKeyResultId], [AssignerId], [StatusId], [IsActive], [CreatedAt], [CreatedById])
SELECT
    (d.DepartmentId - 1) * 7 + t.TemplateId AS Id,
    2,
    CONCAT(N'Bizen ', d.ProjectAlias, N' - ', t.TemplateName),
    CONCAT(N'KPI vận hành thực phẩm cho ', d.DepartmentName, N', phục vụ theo dõi sản xuất, chất lượng, phân phối và công việc.'),
    t.PropertyId,
    t.KPITypeId,
    link.LinkedOkrId,
    link.LinkedKrId,
    d.ManagerId,
    7,
    1,
    GETDATE(),
    d.ManagerId
FROM @DeptProjects d
CROSS JOIN @KpiTemplates t
CROSS APPLY
(
    SELECT ((t.TemplateId - 1) % 3) + 1 AS OkrSlot
) slot
CROSS APPLY
(
    SELECT
        (d.DepartmentId - 1) * 3 + slot.OkrSlot AS LinkedOkrId,
        (((d.DepartmentId - 1) * 3 + slot.OkrSlot - 1) * 3) + slot.OkrSlot AS LinkedKrId
) link;
SET IDENTITY_INSERT [KPIs] OFF;

SET IDENTITY_INSERT [KPIDetails] ON;
INSERT INTO [KPIDetails] ([Id], [KPIId], [TargetValue], [PassThreshold], [FailThreshold], [MeasurementUnit], [IsInverse], [DeadlineDate], [CheckInFrequencyDays], [CheckInDeadlineTime], [ReminderBeforeHours])
SELECT
    (d.DepartmentId - 1) * 7 + t.TemplateId AS Id,
    (d.DepartmentId - 1) * 7 + t.TemplateId AS KPIId,
    target.TargetValue,
    CASE WHEN t.IsInverse = 1 THEN target.TargetValue ELSE ROUND(target.TargetValue * 0.80, 2) END AS PassThreshold,
    CASE WHEN t.IsInverse = 1 THEN ROUND(target.TargetValue * 2.00, 2) ELSE ROUND(target.TargetValue * 0.60, 2) END AS FailThreshold,
    t.MeasurementUnit,
    t.IsInverse,
    CAST('2026-06-30' AS date),
    t.FrequencyDays,
    CAST('10:00:00' AS time),
    24
FROM @DeptProjects d
CROSS JOIN @KpiTemplates t
CROSS APPLY
(
    SELECT CAST(CASE
        WHEN t.TemplateId = 1 THEN
            CASE
                WHEN d.DepartmentId = 1 THEN 20000.00
                WHEN d.DepartmentId = 4 THEN 5000.00
                ELSE 800.00 + (d.DepartmentId * 120.00)
            END
        WHEN t.TemplateId = 4 THEN 3.00 + (d.DepartmentId % 5)
        WHEN t.TemplateId = 5 THEN 15.00 + (d.DepartmentId % 8)
        ELSE t.BaseTarget
    END AS decimal(18,2)) AS TargetValue
) target;
SET IDENTITY_INSERT [KPIDetails] OFF;

INSERT INTO [KPI_Department_Assignments] ([KPIId], [DepartmentId])
SELECT
    (d.DepartmentId - 1) * 7 + t.TemplateId,
    d.DepartmentId
FROM @DeptProjects d
CROSS JOIN @KpiTemplates t;

;WITH ActiveAssignments AS
(
    SELECT [EmployeeId], [DepartmentId]
    FROM [EmployeeAssignments]
    WHERE [IsActive] = 1
),
EmployeeKpis AS
(
    SELECT
        ((DepartmentId - 1) * 7) + (((EmployeeId - 1) % 7) + 1) AS KPIId,
        EmployeeId,
        CAST(0.60 AS decimal(5,2)) AS Weight
    FROM ActiveAssignments
    UNION ALL
    SELECT
        ((DepartmentId - 1) * 7) + (((EmployeeId + 2) % 7) + 1) AS KPIId,
        EmployeeId,
        CAST(0.40 AS decimal(5,2)) AS Weight
    FROM ActiveAssignments
)
INSERT INTO [KPI_Employee_Assignments] ([KPIId], [EmployeeId], [Weight], [Status])
SELECT KPIId, EmployeeId, Weight, N'Active'
FROM EmployeeKpis;
GO

-- KPI check-in seed: partial, approved progress for in-progress KPI scenarios.
-- These rows make dashboards, KPI lists and detail pages show work that is
-- clearly underway but not completed yet.
DECLARE @BizenKpiCheckIns TABLE
(
    RowId INT PRIMARY KEY,
    KPIId INT NOT NULL,
    EmployeeId INT NOT NULL,
    ReviewerId INT NULL,
    SlotIndex INT NOT NULL,
    CheckInDate DATETIME2 NOT NULL,
    DeadlineAt DATETIME2 NOT NULL,
    TargetValue DECIMAL(18,2) NOT NULL,
    ContributorCount INT NOT NULL,
    ProgressRatio DECIMAL(9,4) NOT NULL,
    ExpectedRatio DECIMAL(9,4) NOT NULL
);

;WITH RankedAssignments AS
(
    SELECT
        a.KPIId,
        a.EmployeeId,
        k.AssignerId AS ReviewerId,
        COALESCE(kd.TargetValue, 0) AS TargetValue,
        ROW_NUMBER() OVER
        (
            PARTITION BY a.KPIId
            ORDER BY
                CASE WHEN a.EmployeeId IN (3, 4, 5) THEN 0 ELSE 1 END,
                a.EmployeeId
        ) AS AssignmentRank
    FROM [KPI_Employee_Assignments] a
    INNER JOIN [KPIs] k ON k.Id = a.KPIId
    INNER JOIN [KPIDetails] kd ON kd.KPIId = k.Id
    WHERE (a.Status IS NULL OR a.Status = N'Active')
      AND k.StatusId = 7
      AND k.IsActive = 1
      AND COALESCE(kd.IsInverse, 0) = 0
      AND COALESCE(kd.TargetValue, 0) > 0
),
SelectedAssignments AS
(
    SELECT
        KPIId,
        EmployeeId,
        ReviewerId,
        TargetValue
    FROM RankedAssignments
    WHERE AssignmentRank <= 2
),
ContributorCounts AS
(
    SELECT
        KPIId,
        COUNT(*) AS ContributorCount
    FROM SelectedAssignments
    GROUP BY KPIId
),
BizenRows AS
(
    SELECT
        ROW_NUMBER() OVER (ORDER BY sa.KPIId, sa.EmployeeId, slot.SlotIndex) AS RowId,
        sa.KPIId,
        sa.EmployeeId,
        sa.ReviewerId,
        slot.SlotIndex,
        DATEADD(
            MINUTE,
            sa.EmployeeId % 35,
            CASE slot.SlotIndex
                WHEN 1 THEN CAST('2026-04-08T09:15:00' AS DATETIME2)
                ELSE CAST('2026-04-21T09:15:00' AS DATETIME2)
            END
        ) AS CheckInDate,
        CASE slot.SlotIndex
            WHEN 1 THEN CAST('2026-04-08T10:00:00' AS DATETIME2)
            ELSE CAST('2026-04-21T10:00:00' AS DATETIME2)
        END AS DeadlineAt,
        sa.TargetValue,
        cc.ContributorCount,
        CAST(CASE slot.SlotIndex
            WHEN 1 THEN 0.08 + ((sa.KPIId + sa.EmployeeId) % 6) * 0.03
            ELSE 0.18 + ((sa.KPIId + sa.EmployeeId) % 10) * 0.06
        END AS DECIMAL(9,4)) AS ProgressRatio,
        CAST(CASE slot.SlotIndex
            WHEN 1 THEN 0.20
            ELSE 0.45
        END AS DECIMAL(9,4)) AS ExpectedRatio
    FROM SelectedAssignments sa
    INNER JOIN ContributorCounts cc ON cc.KPIId = sa.KPIId
    CROSS JOIN (VALUES (1), (2)) AS slot(SlotIndex)
)
INSERT INTO @BizenKpiCheckIns
(
    RowId,
    KPIId,
    EmployeeId,
    ReviewerId,
    SlotIndex,
    CheckInDate,
    DeadlineAt,
    TargetValue,
    ContributorCount,
    ProgressRatio,
    ExpectedRatio
)
SELECT
    RowId,
    KPIId,
    EmployeeId,
    ReviewerId,
    SlotIndex,
    CheckInDate,
    DeadlineAt,
    TargetValue,
    ContributorCount,
    ProgressRatio,
    ExpectedRatio
FROM BizenRows;

SET IDENTITY_INSERT [KPICheckIns] ON;
INSERT INTO [KPICheckIns]
(
    [Id],
    [EmployeeId],
    [KPIId],
    [SubmittedById],
    [CheckInDate],
    [DeadlineAt],
    [IsLate],
    [StatusId],
    [FailReasonId],
    [ReviewStatus],
    [ReviewedById],
    [ReviewedAt],
    [ReviewComment],
    [ReviewScore]
)
SELECT
    RowId,
    EmployeeId,
    KPIId,
    EmployeeId,
    CheckInDate,
    DeadlineAt,
    CASE WHEN ProgressRatio < ExpectedRatio THEN 1 ELSE 0 END,
    CASE
        WHEN ProgressRatio >= 0.70 THEN 3
        WHEN ProgressRatio >= ExpectedRatio THEN 1
        WHEN ProgressRatio < 0.25 THEN 4
        ELSE 2
    END,
    CASE
        WHEN ProgressRatio < 0.25 THEN 1
        WHEN ProgressRatio < ExpectedRatio THEN 3
        ELSE NULL
    END,
    N'Approved',
    ReviewerId,
    DATEADD(HOUR, 2, CheckInDate),
    CASE
        WHEN ProgressRatio >= ExpectedRatio THEN N'Dữ liệu Bizen: tiến độ đang đi đúng hướng, tiếp tục bám mốc Q2.'
        ELSE N'Dữ liệu Bizen: KPI đang thực hiện dở, cần tăng tốc trong các lần check-in tiếp theo.'
    END,
    CAST(ProgressRatio * 100 AS DECIMAL(5,2))
FROM @BizenKpiCheckIns;
SET IDENTITY_INSERT [KPICheckIns] OFF;

SET IDENTITY_INSERT [CheckInDetails] ON;
INSERT INTO [CheckInDetails]
(
    [Id],
    [CheckInId],
    [AchievedValue],
    [ProgressPercentage],
    [ExpectedValueAtDeadline],
    [ScheduleProgressPercentage],
    [Note]
)
SELECT
    RowId,
    RowId,
    ROUND((TargetValue * ProgressRatio) / ContributorCount, 2),
    CAST(ProgressRatio * 100 AS DECIMAL(18,2)),
    ROUND((TargetValue * ExpectedRatio) / ContributorCount, 2),
    CAST(ROUND((ProgressRatio / ExpectedRatio) * 100, 2) AS DECIMAL(18,2)),
    CASE SlotIndex
        WHEN 1 THEN N'Check-in Bizen đầu kỳ: đã bắt đầu triển khai, còn nhiều hạng mục đang mở.'
        ELSE N'Check-in Bizen giữa kỳ: KPI đang làm dở, có số liệu tiến độ nhưng chưa đạt mục tiêu.'
    END
FROM @BizenKpiCheckIns;
SET IDENTITY_INSERT [CheckInDetails] OFF;

SET IDENTITY_INSERT [CheckInHistoryLogs] ON;
INSERT INTO [CheckInHistoryLogs] ([Id], [CheckInId], [SnapshotData], [LogTime])
SELECT
    RowId,
    RowId,
    CONCAT(
        N'Bizen partial KPI progress | KPI #', KPIId,
        N' | Employee #', EmployeeId,
        N' | Progress ', CAST(CAST(ProgressRatio * 100 AS DECIMAL(5,2)) AS NVARCHAR(20)), N'%'
    ),
    DATEADD(MINUTE, 5, CheckInDate)
FROM @BizenKpiCheckIns;
SET IDENTITY_INSERT [CheckInHistoryLogs] OFF;
GO

