-- SEED DATA 100 RECORDS PER TABLE - MANAGE KPI OR OKR SYSTEM
-- Multi-Tenancy Aware & SQL Server Unicode Safe (N'...')
-- ============================================================

SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
