    VALUES (1, N'Legacy tenant', N'legacy', 1, SYSUTCDATETIME());
    SET IDENTITY_INSERT [Tenants] OFF;
END
GO

IF NOT EXISTS (SELECT 1 FROM sys.default_constraints WHERE name = 'DF_AIGenerationHistories_TenantId')
