-- ============================================================
-- PERFECT ALIGNMENT BETWEEN OKR PROGRESS & LINKED KPI PROGRESS
-- OKR Status <-> Linked KPI Status <-> CheckIn Achieved Progress
-- ============================================================

SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO

EXEC sys.sp_set_session_context @key = N'TenantId', @value = 1, @read_only = 0;
GO

-- 1. UPDATE ALIGNED PROGRESS FOR ALL LINKED KPIs & CHECK-INS BASED ON OKR STATUS


-- Align OKR Key Results progress with OKR Status
UPDATE kr
SET kr.[CurrentValue] = kr.[TargetValue],
    kr.[ResultStatus] = N'Hoàn thành'
FROM [OKRKeyResults] kr
JOIN [OKRs] o ON kr.[OKRId] = o.[Id]
WHERE o.[StatusId] = 3;

UPDATE kr
SET kr.[CurrentValue] = ROUND(kr.[TargetValue] * 0.65, 2),
    kr.[ResultStatus] = N'Đang thực hiện'
FROM [OKRKeyResults] kr
JOIN [OKRs] o ON kr.[OKRId] = o.[Id]
WHERE o.[StatusId] = 2;

UPDATE kr
SET kr.[CurrentValue] = ROUND(kr.[TargetValue] * 0.15, 2),
    kr.[ResultStatus] = N'Đang thực hiện'
FROM [OKRKeyResults] kr
JOIN [OKRs] o ON kr.[OKRId] = o.[Id]
WHERE o.[StatusId] = 1;

UPDATE kr
SET kr.[CurrentValue] = ROUND(kr.[TargetValue] * 0.30, 2),
    kr.[ResultStatus] = N'Đang thực hiện'
FROM [OKRKeyResults] kr
JOIN [OKRs] o ON kr.[OKRId] = o.[Id]
WHERE o.[StatusId] = 4;

-- Align KPI StatusId with linked OKR StatusId
-- OKR 3 (Completed) -> KPI 8 (Completed)
UPDATE k
SET k.[StatusId] = 8
FROM [KPIs] k
JOIN [OKRs] o ON k.[OKRId] = o.[Id]
WHERE o.[StatusId] = 3;

-- OKR 2 (InProgress) -> KPI 7 (InProgress)
UPDATE k
SET k.[StatusId] = 7
FROM [KPIs] k
JOIN [OKRs] o ON k.[OKRId] = o.[Id]
WHERE o.[StatusId] = 2;

-- OKR 1 (Draft) -> KPI 6 (Draft)
UPDATE k
SET k.[StatusId] = 6
FROM [KPIs] k
JOIN [OKRs] o ON k.[OKRId] = o.[Id]
WHERE o.[StatusId] = 1;

-- OKR 4 (Behind) -> KPI 9 (Behind)
UPDATE k
SET k.[StatusId] = 9
FROM [KPIs] k
JOIN [OKRs] o ON k.[OKRId] = o.[Id]
WHERE o.[StatusId] = 4;

-- Align KPICheckIns & CheckInDetails with KPI Status
-- Completed KPIs (StatusId = 8) -> CheckIn StatusId = 5 (Hoàn thành), 100% Progress
UPDATE c
SET c.[StatusId] = 5,
    c.[ReviewStatus] = N'Approved',
    c.[ReviewScore] = 95.00,
    c.[IsLate] = 0
FROM [KPICheckIns] c
JOIN [KPIs] k ON c.[KPIId] = k.[Id]
WHERE k.[StatusId] = 8;

UPDATE cd
SET cd.[ProgressPercentage] = 100.00,
    cd.[ScheduleProgressPercentage] = 100.00,
    cd.[AchievedValue] = cd.[ExpectedValueAtDeadline],
    cd.[Note] = N'Đã hoàn thành 100% chỉ tiêu KPI tương ứng với OKR.'
FROM [CheckInDetails] cd
JOIN [KPICheckIns] c ON cd.[CheckInId] = c.[Id]
JOIN [KPIs] k ON c.[KPIId] = k.[Id]
WHERE k.[StatusId] = 8;

-- InProgress KPIs (StatusId = 7) -> CheckIn StatusId = 1 (Đúng tiến độ), 65% Progress
UPDATE c
SET c.[StatusId] = 1,
    c.[ReviewStatus] = N'Approved',
    c.[ReviewScore] = 82.00,
    c.[IsLate] = 0
FROM [KPICheckIns] c
JOIN [KPIs] k ON c.[KPIId] = k.[Id]
WHERE k.[StatusId] = 7;

UPDATE cd
SET cd.[ProgressPercentage] = 65.00,
    cd.[ScheduleProgressPercentage] = 65.00,
    cd.[AchievedValue] = ROUND(cd.[ExpectedValueAtDeadline] * 0.65, 2),
    cd.[Note] = N'Tiến độ KPI đang đạt 65% đúng tiến độ với OKR liên kết.'
FROM [CheckInDetails] cd
JOIN [KPICheckIns] c ON cd.[CheckInId] = c.[Id]
JOIN [KPIs] k ON c.[KPIId] = k.[Id]
WHERE k.[StatusId] = 7;

-- Draft KPIs (StatusId = 6) -> CheckIn StatusId = 1 (Mới tạo), 15% Progress
UPDATE c
SET c.[StatusId] = 1,
    c.[ReviewStatus] = N'Pending',
    c.[ReviewScore] = 65.00,
    c.[IsLate] = 0
FROM [KPICheckIns] c
JOIN [KPIs] k ON c.[KPIId] = k.[Id]
WHERE k.[StatusId] = 6;

UPDATE cd
SET cd.[ProgressPercentage] = 15.00,
    cd.[ScheduleProgressPercentage] = 15.00,
    cd.[AchievedValue] = ROUND(cd.[ExpectedValueAtDeadline] * 0.15, 2),
    cd.[Note] = N'Bắt đầu triển khai KPI, tiến độ đạt 15% theo OKR.'
FROM [CheckInDetails] cd
JOIN [KPICheckIns] c ON cd.[CheckInId] = c.[Id]
JOIN [KPIs] k ON c.[KPIId] = k.[Id]
WHERE k.[StatusId] = 6;

-- Behind KPIs (StatusId = 9) -> CheckIn StatusId = 2 (Chậm tiến độ), 30% Progress, IsLate = 1
UPDATE c
SET c.[StatusId] = 2,
    c.[ReviewStatus] = N'Approved',
    c.[ReviewScore] = 55.00,
    c.[IsLate] = 1,
    c.[FailReasonId] = 1
FROM [KPICheckIns] c
JOIN [KPIs] k ON c.[KPIId] = k.[Id]
WHERE k.[StatusId] = 9;

UPDATE cd
SET cd.[ProgressPercentage] = 30.00,
    cd.[ScheduleProgressPercentage] = 30.00,
    cd.[AchievedValue] = ROUND(cd.[ExpectedValueAtDeadline] * 0.30, 2),
    cd.[Note] = N'KPI đang gặp khó khăn chậm tiến độ (đạt 30%) tương ứng với OKR bị chậm.'
FROM [CheckInDetails] cd
JOIN [KPICheckIns] c ON cd.[CheckInId] = c.[Id]
JOIN [KPIs] k ON c.[KPIId] = k.[Id]
WHERE k.[StatusId] = 9;
GO


PRINT N'';
PRINT N'=== PERFECT ALIGNMENT BETWEEN KPI & OKR PROGRESS COMPLETED ===';
PRINT N'';
GO

